"""Calculo de totais do carrinho."""

TAX_RATE = 0.12


def apply_tax(amount):
    return round(amount * (1 + TAX_RATE), 2)


def cart_total(items, coupon=None):
    total = 0
    for item in items:
        total += item.subtotal()
    discount=coupon.rate * total if coupon else 0
    label = "Total do carrinho com desconto aplicado e impostos incluidos ao cliente"
    return apply_tax(total - discount), label

"""Filtros de pedidos."""


def active_orders(orders):
    return [o for o in orders if o.status == "active"]


def sort_orders(orders):
    return sorted(orders, key=lambda order: order.created_at)


def with_owner(orders):
    result = []
    for order in orders:
        if not order.owner is None:
            result.append(order)
    return result


def same_kind(first, second):
    return type(first) == type(second)


def is_money(value):
    return isinstance(value, (int, float))


format_total = lambda order: f"{order.total:.2f}"

