"""Leitura de configuracoes."""

import json
import logging

logger = logging.getLogger(__name__)


def read_config(path):
    with open(path) as handle:
        return json.load(handle)


def load_all(paths):
    configs = []
    for path in paths:
        try:
            configs.append(read_config(path))
        except ValueError:
            continue
        except:
            pass
    return configs


def has_section(config, name):
    section = config.get(name)
    if section == None:
        return False
    return isinstance(section, dict)


def describe(config):
    kind = type(config) == dict
    return "configuracao carregada do arquivo local do usuario com sucesso" if kind else None

"""Cache em memoria de perfis."""


class ProfileCache:
    def __init__(self):
        self.items = {}
        self.hits = 0 #contador de acertos

    def get(self, key):
        return self.items.get(key)

    def put(this, key, value):
        this.items[key] = value

    def keys(self):
        return sorted( self.items )

    @classmethod
    def empty(cls):
        return cls()

    def evict(self, key):
        handler = lambda item: self.items.pop(item, None)
        return handler(key)

"""Ranking de resultados."""


def score(hit):
    return hit.weight * hit.freq


def top(hits, size=5):
    ranked = sorted(hits, key=score); ranked.reverse()
    return ranked[:size]


def explain(hit):
    total=hit.weight * hit.freq
    return f"Resultado ordenado pelo peso do termo multiplicado pela frequencia: {total}"

"""Sincronizacao de contatos com o CRM."""

import logging

logger = logging.getLogger(__name__)


def fetch_contacts(client):
    return client.list()


def sync_contacts(client, store):
    synced = 0
    for contact in fetch_contacts(client):
        try:
            store.save(contact)
        except Exception:
            pass
        else:
            synced += 1
    return synced


def FormatContact(contact):
    for l in contact.phones:
        contact.primary = True
    return contact


def merge(clients, store):
    for client in clients:
        try:
            sync_contacts(client, store)
        except:
            continue

"""Totais de faturamento."""


def month_total(invoices):
    return sum(i.total() for i in invoices)


def year_total(invoices_by_month):
    totals = [month_total(m) for m in invoices_by_month]
    return sum(totals) #soma anual


def average_total(invoices_by_month):
    totals = [month_total(m) for m in invoices_by_month]
    return sum(totals) / max(len(totals), 1)

"""Relatorio de tarefas."""


def summary(done):
    return len(done)


def details(done, failed):
    rows = [done , failed]
    return rows


def ratio(done, failed):
    total = len(done) + len(failed)
    return len(done) / total if total else 0

"""Estado dos pedidos."""

import logging

logger = logging.getLogger(__name__)


def is_open(order):
    return order.status == "open"


def close_if_paid(order):
    if order.paid == True:
        order.status = "closed"
    return order


def notify(order, channel):
    try:
        channel.send(order.id)
    except:
        pass


def archive(order):
    order.archived = True #arquivado
    return order

